mapper.select:
select
c1.C_Name_History as chSupervisorNameHistory, c2.C_Name_History as chUserUnitNameHistory, c3.C_Name_History as chContractorNameHistory, c1.C_Name as chSupervisorName, c2.C_Name as chUserUnitName, c3.C_Name as chContractorName, c1.C_Abbreviation as chSupervisorAbbName, c2.C_Abbreviation as chUserUnitAbbName, c3.C_Abbreviation as chContractorAbbName, mn.* from Completion_Handover mn
left join Completion_Acceptance ca on ca.Ca_Id=mn.Ca_Id left join SYS_Company c1 on c1.C_Id=mn.Ch_Supervisor_Id left join SYS_Company c2 on c2.C_Id=mn.Ch_User_Unit_Id left join SYS_Company c3 on c3.C_Id=mn.Ch_Contractor_Id ${params.authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Ch_Create_Time DESC
